        oldItem.transform.rotation=HeldFrame*Quaternion.Euler(0,35,0);newItem.transform.rotation=HeldFrame*Quaternion.Euler(0,35,0);yield return null;Shot("08_B_Left_R03_Right_35_SameFrame","Left B and right R03 both +35 held yaw; exactly shared exposure and lighting");
