        View(new Vector3(-.22f,.22f,-.50f),new Vector3(0,.175f,0));for(int i=0;i<120;i++){newItem.transform.rotation=HeldFrame*Quaternion.Euler(0,Mathf.Lerp(-22,22,i/119f),0);yield return null;SaveRender(output+"/turn-frames/frame_"+i.ToString("D4")+".jpg",true);}newItem.transform.rotation=HeldFrame;
        var optics=QuickOptics();while(optics.MoveNext())yield return optics.Current;
