    static float Max(Color c)=>Mathf.Max(Mathf.Abs(c.r),Mathf.Max(Mathf.Abs(c.g),Mathf.Abs(c.b)));
    static void ViewItem(Vector3 p,Vector3 at){camera.transform.position=newItem.transform.TransformPoint(p);camera.transform.LookAt(newItem.transform.TransformPoint(at));}
    static void View(Vector3 p,Vector3 at){camera.transform.position=HeldFrame*p;camera.transform.LookAt(HeldFrame*at);}
    static void Shot(string name,string caption){SaveRender(images+"/"+name+".png",false);media.Add(new Media{path=images+"/"+name+".png",caption=caption,cameraPosition=camera.transform.position.ToString("F5"),cameraEuler=camera.transform.eulerAngles.ToString("F4"),modelEuler=newItem.transform.eulerAngles.ToString("F4"),lightEuler=sun.transform.eulerAngles.ToString("F4"),stage=inputs.stage,modelSha256=inputs.modelSha256});}
    static void SaveRender(string path,bool jpg){RenderPipeline.SubmitRenderRequest(camera,new UniversalRenderPipeline.SingleCameraRequest{destination=target});var prev=RenderTexture.active;RenderTexture.active=target;pixels.ReadPixels(new Rect(0,0,1280,960),0,0);pixels.Apply();RenderTexture.active=prev;var srgb=new Texture2D(1280,960,TextureFormat.RGB24,false);srgb.SetPixels(pixels.GetPixels().Select(c=>c.gamma).ToArray());srgb.Apply();File.WriteAllBytes(path,jpg?srgb.EncodeToJPG(94):srgb.EncodeToPNG());Object.Destroy(srgb);}
    static void Require(bool ok,string message){if(!ok)throw new Exception(message);report.Add("PASS "+message);if(!string.IsNullOrEmpty(output))File.WriteAllLines(output+"/progress.txt",report);}
    static void Step(){try{if(++frame>450)throw new Exception("Bounded first-look frame limit");if(routine.MoveNext())return;QingGuiR03ReviewTick.Tick=null;File.WriteAllLines(output+"/result.txt",report);EditorApplication.Exit(0);}catch(Exception e){Fail(e);}}
    static void Fail(Exception e){QingGuiR03ReviewTick.Tick=null;var p=output??Logs+"/startup";Directory.CreateDirectory(p);File.WriteAllText(p+"/failure.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(3);}
}
